<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\RolePermission;use Illuminate\Http\Request;
class PermissionController extends Controller {public const ROLES=['admin','manage_admin','qa_admin','super_admin','Manager','HOD','Director','Executive'];public const PERMISSIONS=['dashboard.view','employees.manage','departments.manage','attendance.view','team.view','requests.view','requests.review','requests.finalize','reports.export'];public function index(Request $r){abort_unless($r->user()->isSuperAdmin(),403);$assigned=RolePermission::get()->groupBy('role')->map->pluck('permission');return view('admin.permissions',compact('assigned'));}public function update(Request $r){abort_unless($r->user()->isSuperAdmin(),403);$data=$r->validate(['permissions'=>'nullable|array']);foreach(self::ROLES as $role){RolePermission::where('role',$role)->delete();foreach($data['permissions'][$role]??[] as $permission)if(in_array($permission,self::PERMISSIONS,true))RolePermission::create(compact('role','permission'));}return back()->with('success','Permission matrix updated.');}}
